/* Adria trainer: all learning state stays on this device. */
(()=>{'use strict';
const B=window.ADRIA_BANK;if(!B){document.getElementById('app').textContent='Der Fragenkatalog konnte nicht geladen werden. Bitte lade die Seite erneut, sobald du online bist.';return;}
const Q=B.questions,byId=new Map(Q.map(q=>[q.id,q])),topics=[...new Set(Q.map(q=>q.topic))],KEY='adria-progress-v1';
const $=s=>document.querySelector(s),$$=s=>[...document.querySelectorAll(s)],esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const fresh=()=>({version:1,cards:{},history:[],session:null});let data=fresh(),storageOK=true,view='home',catalogTopic='',catalogText='',toastTimer;
function toast(s){const n=$('#notice');n.textContent=s;n.style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>n.style.display='none',4500);}
function validCards(cards){const out={};if(!cards||typeof cards!=='object'||Array.isArray(cards))throw Error('Ungültiger Fortschritt');for(const [id,v] of Object.entries(cards)){if(!byId.has(id))continue;if(!v||![0,.5,1].includes(v.last)||!Number.isSafeInteger(v.attempts)||v.attempts<1||v.attempts>100000||!Number.isSafeInteger(v.streak)||v.streak<0||v.streak>100000||!Number.isFinite(v.due)||!Number.isFinite(v.lastAt))throw Error('Ungültiger Lerneintrag');out[id]={last:v.last,attempts:v.attempts,streak:v.streak,due:v.due,lastAt:v.lastAt};}return out;}
function sessionValid(s){return !!s&&['exam','quick','learn','weak','oral','partner'].includes(s.mode)&&Array.isArray(s.ids)&&s.ids.length>0&&s.ids.length<=Q.length&&s.ids.every(id=>byId.has(id))&&new Set(s.ids).size===s.ids.length&&Number.isInteger(s.pos)&&s.pos>=0&&s.pos<s.ids.length&&s.responses&&typeof s.responses==='object'&&s.orders&&typeof s.orders==='object'&&s.ids.every(id=>{const q=byId.get(id);return !q.options||(Array.isArray(s.orders[id])&&s.orders[id].length===q.options.length&&new Set(s.orders[id]).size===q.options.length&&s.orders[id].every(o=>q.options.includes(o)));})&&['answer','review','result'].includes(s.phase)&&Number.isFinite(s.started)&&s.ids.every(id=>{const r=s.responses[id];return !r||(typeof r==='object'&&(!('score'in r)||r.score===null||[0,.5,1].includes(r.score))&&(!r.choice||byId.get(id).options?.includes(r.choice)));});}
try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(parsed.version!==1)throw Error('Version');data={version:1,cards:validCards(parsed.cards),history:Array.isArray(parsed.history)?parsed.history.filter(x=>x&&Number.isFinite(x.at)&&Number.isFinite(x.total)&&Number.isFinite(x.score)&&x.total>0&&x.score>=0&&x.score<=x.total).slice(-50):[],session:sessionValid(parsed.session)?parsed.session:null};}}catch{data=fresh();storageOK=false;}
function save(){try{localStorage.setItem(KEY,JSON.stringify(data));return true;}catch{storageOK=false;toast('Speichern nicht möglich. Sichere deinen Fortschritt als Datei.');return false;}}
function shuffle(a){a=[...a];for(let i=a.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[a[i],a[j]]=[a[j],a[i]];}return a;}
function choose(pool,n){const groups=new Map();for(const q of shuffle(pool)){if(!groups.has(q.topic))groups.set(q.topic,[]);groups.get(q.topic).push(q);}const result=[];while(result.length<Math.min(n,pool.length)){for(const topic of shuffle([...groups.keys()])){const group=groups.get(topic);if(group.length)result.push(group.pop());if(result.length>=Math.min(n,pool.length))break;}}return shuffle(result);}
function makeSession(mode,pool,n){const selection=choose(pool,n);return {id:Date.now()+'-'+Math.random().toString(16).slice(2),mode,ids:selection.map(q=>q.id),orders:Object.fromEntries(selection.filter(q=>q.options).map(q=>[q.id,shuffle(q.options)])),responses:{},pos:0,phase:'answer',revealed:false,started:Date.now(),saved:false};}
function record(id,score){const old=data.cards[id]||{attempts:0,streak:0};const streak=score===1?old.streak+1:0;data.cards[id]={attempts:old.attempts+1,streak,last:score,lastAt:Date.now(),due:Date.now()+(score===1?Math.min(30,2**Math.min(streak-1,5)):score===.5?.5:.1)*86400000};}
function commitRating(s,q,score){const response=s.responses[q.id]||(s.responses[q.id]={});if(response.recorded)return;response.score=score;response.recorded=true;record(q.id,score);}
const modes={exam:'Testprüfung',quick:'Schnellrunde',learn:'Themen lernen',weak:'Schwachstellen',oral:'Mündlich üben',partner:'Partnerprüfung'};
function progress(){const seen=Object.values(data.cards);return {seen:seen.length,secure:seen.filter(s=>s.streak>=2).length,weak:seen.filter(s=>s.last<1).length,due:seen.filter(s=>s.due<=Date.now()).length};}
function goto(render){render();window.scrollTo({top:0,behavior:'instant'});const h=$('main h1');if(h){h.tabIndex=-1;h.focus({preventScroll:true});}}
function home(){view='home';const p=progress();$('#app').innerHTML=`<div class="dashboard"><section class="welcome"><div><div class="eyebrow muted">Dein Kurs zum Küstenpatent</div><h1>Bereit für die<br>nächste Etappe?</h1><p class="muted">${Q.length} Fragen. Dein Tempo. Dein Fortschritt.</p></div><button class="textbtn" id="catalogBtn">Fragenkatalog ansehen</button></section><section class="card launch"><div class="eyebrow">Prüfungsmodus</div><h2>Leinen los.<br>Wissen auf die Probe.</h2><p>Gemischte Fragen aus allen Themen.<br>Die Auflösung kommt am Schluss.</p><div class="controls"><div class="compact"><label for="examCount">Fragen</label><select id="examCount"><option>10</option><option selected>20</option><option>30</option></select></div><button id="examStart" class="primary" style="align-self:end">Testprüfung starten →</button></div></section><div class="stack"><button class="mode" data-mode="quick"><span class="glyph" aria-hidden="true">↗</span><span><strong>Schnellrunde</strong><small>10 Fragen für zwischendurch</small></span></button><button class="mode" data-mode="weak"><span class="glyph" aria-hidden="true">↻</span><span><strong>Schwachstellen üben</strong><small>${p.weak?`${p.weak} unsichere Fragen`:'Nach deiner ersten Lernrunde'}</small></span></button><button class="mode" data-mode="partner"><span class="glyph" aria-hidden="true">☷</span><span><strong>Gegenseitig abfragen</strong><small>Fragen vorlesen · Lösungen aufdecken</small></span></button></div></div>${data.session?`<div class="card space row"><div><strong>${modes[data.session.mode]} fortsetzen</strong><p class="muted">${data.session.phase==='answer'?`Frage ${data.session.pos+1} von ${data.session.ids.length}`:data.session.phase==='review'?'Offene Antworten bewerten':'Ergebnis ansehen'}</p></div><button id="resume" class="primary">Weiter</button></div>`:''}<div class="metrics"><div class="metric"><strong>${p.seen}<span> / ${Q.length}</span></strong><span>Fragen bearbeitet</span></div><div class="metric"><strong>${p.secure}</strong><span>Zweimal in Folge gewusst</span></div><div class="metric"><strong>${p.due}</strong><span>Zur Wiederholung fällig</span></div></div>${p.due?'<button class="textbtn space" id="dueBtn">Fällige Fragen wiederholen →</button>':''}<div class="sectionhead"><h2>Thema für Thema</h2><button class="textbtn" data-mode="oral">Mündlich üben</button></div><div class="topics">${topics.map((t,i)=>{const qs=Q.filter(q=>q.topic===t),mastered=qs.filter(q=>data.cards[q.id]?.streak>=2).length;return `<button class="topic" data-topic="${esc(t)}"><span class="eyebrow muted">${String(i+1).padStart(2,'0')}</span><h3>${esc(t)}</h3><span class="muted">${qs.length} Fragen · ${mastered} sicher</span><div class="bar" aria-label="${mastered} von ${qs.length} sicher"><span style="width:${100*mastered/qs.length}%"></span></div></button>`}).join('')}</div>${!storageOK?'<p class="caution space">Lokaler Speicher ist nicht verfügbar oder konnte nicht gelesen werden. Bitte exportiere deinen Fortschritt vor dem Schließen.</p>':''}<p class="muted space" style="font-size:.85rem">Lernstand auf diesem Gerät · keine Synchronisierung zwischen euren Handys.</p>`;
 $('#examStart').onclick=()=>start('exam',null,Number($('#examCount').value));$('#catalogBtn').onclick=()=>goto(catalog);$$('[data-mode]').forEach(b=>b.onclick=()=>start(b.dataset.mode));$$('[data-topic]').forEach(b=>b.onclick=()=>start('learn',b.dataset.topic));if($('#resume'))$('#resume').onclick=()=>goto(renderSession);if($('#dueBtn'))$('#dueBtn').onclick=()=>start('learn',null,20,Q.filter(q=>data.cards[q.id]?.due<=Date.now()));}
function start(mode,topic=null,count=null,override=null){if(!modes[mode])throw Error('Unbekannter Modus');let pool=override||Q.filter(q=>!topic||q.topic===topic);if(mode==='weak')pool=pool.filter(q=>data.cards[q.id]?.last<1);if(!pool.length){toast('Hier gibt es noch keine Fragen. Starte zuerst eine Lernrunde.');return false;}if(data.session?.phase!=='result'&&data.session&&!confirm('Die laufende Runde durch eine neue ersetzen? Bereits bewertete Fragen bleiben gespeichert.'))return false;
 if(['learn','weak'].includes(mode)){pool=shuffle(pool).sort((a,b)=>{const priority=q=>{const c=data.cards[q.id];return c?.last<1?0:!c?1:c.due<=Date.now()?2:3;};return priority(a)-priority(b);});pool=pool.slice(0,count||(topic?Math.min(20,pool.length):10));}
data.session=makeSession(mode,pool,count||(mode==='exam'?20:mode==='learn'&&topic?Math.min(20,pool.length):10));save();goto(renderSession);return true;}
function isChoice(q,s){return q.type==='choice'&&!['oral','partner'].includes(s.mode);}
function sourceHTML(q){return `<div class="source"><a href="${B.sources.skript.url}#page=${q.page}" target="_blank" rel="noopener">Skript S. ${q.page} ↗</a>${q.sources.filter(x=>x!=='skript').map(k=>` · <a href="${B.sources[k].url}" target="_blank" rel="noopener">${esc(B.sources[k].title)} ↗</a>`).join('')}</div>`;}
function answerHTML(q){return `<section class="answer"><div class="eyebrow">Musterantwort</div><p><strong>${esc(q.answer)}</strong></p><p class="explain">${esc(q.explanation)}</p>${sourceHTML(q)}</section>${q.note?`<p class="caution">${esc(q.note)}</p>`:''}`;}
function imageHTML(q){return q.image?`<img class="diagram${q.day?' day':''}" src="./${q.image}" alt="${esc(q.alt)}">${q.imageCaption?`<p class="muted" style="font-size:.8rem;text-align:center">${esc(q.imageCaption)}</p>`:''}`:'';}
function renderSession(){view='session';const s=data.session;if(!s){home();return;}if(s.phase==='review'){renderReview();return;}if(s.phase==='result'){renderResult();return;}const q=byId.get(s.ids[s.pos]),r=s.responses[q.id]||{},choice=isChoice(q,s),answered=s.mode!=='exam'&&r.recorded;
$('#app').innerHTML=`<div class="question-shell"><div class="qtop"><button class="textbtn" id="pause">← Pause</button><span class="muted">${modes[s.mode]} · <span class="count">${s.pos+1} / ${s.ids.length}</span></span></div><div class="bar"><span style="width:${100*s.pos/s.ids.length}%"></span></div><section class="card qcard"><div class="tags"><span class="tag">${esc(q.topic)}</span><span class="tag">${esc(q.difficulty)}</span>${s.mode!=='exam'&&q.sample?'<span class="tag">Beispielfrage vertieft</span>':''}</div><h1>${esc(q.question)}</h1>${imageHTML(q)}${choice?`<div class="choices" role="group" aria-label="Antwort auswählen">${s.orders[q.id].map((o,i)=>`<button class="choice ${r.choice===o?'selected':''} ${answered&&o===q.answer?'correct':''} ${answered&&r.choice===o&&o!==q.answer?'wrong':''}" data-option="${i}" aria-pressed="${r.choice===o}" ${answered?'disabled':''}><b aria-hidden="true">${String.fromCharCode(65+i)}</b><span>${esc(o)}</span></button>`).join('')}</div>`:s.mode==='exam'?`<label for="written">Deine Antwort</label><textarea id="written" placeholder="Stichworte genügen. Nach der Prüfung vergleichst du mit der Musterlösung.">${esc(r.text||'')}</textarea>`:`<p class="muted">${s.mode==='partner'?'Lass die andere Person antworten. Decke erst danach die Lösung auf.':'Antworte zuerst laut oder im Kopf. Dann vergleiche mit der Lösung.'}</p>`}${s.mode==='exam'?`<div class="controls space"><button class="secondary" id="previous" ${s.pos===0?'disabled':''}>Zurück</button><button class="primary" id="next">${s.pos===s.ids.length-1?'Prüfung abgeben':'Weiter →'}</button></div><p class="muted" style="font-size:.8rem">${Object.keys(s.responses).filter(id=>s.responses[id].choice||s.responses[id].text?.trim()).length} von ${s.ids.length} beantwortet · Überspringen ist möglich.</p>`:answered||s.revealed?`${answerHTML(q)}${answered?`<p class="muted">${r.score===1?'✓ Gewusst':r.score===.5?'◐ Teilweise gewusst':'↻ Kommt wieder in die Wiederholung'}</p><button class="primary wide space" id="continue">${s.pos===s.ids.length-1?'Ergebnis ansehen':'Nächste Frage →'}</button>`:`<p class="muted">Wie vollständig war die Antwort?</p>${ratings()}`}`:`<button class="primary wide space" id="reveal" ${choice&&!r.choice?'disabled':''}>${choice?'Antwort prüfen':'Lösung aufdecken'}</button>`}</section></div>`;
$('#pause').onclick=()=>{save();goto(home);};$$('[data-option]').forEach(b=>b.onclick=()=>{s.responses[q.id]={...r,choice:s.orders[q.id][Number(b.dataset.option)]};save();renderSession();});if($('#written'))$('#written').oninput=e=>{s.responses[q.id]={...s.responses[q.id],text:e.target.value.slice(0,10000)};save();};if($('#previous'))$('#previous').onclick=()=>{s.pos--;save();goto(renderSession);};if($('#next'))$('#next').onclick=()=>{if(s.pos<s.ids.length-1){s.pos++;save();goto(renderSession);}else submitExam();};if($('#reveal'))$('#reveal').onclick=()=>{s.revealed=true;if(choice)commitRating(s,q,r.choice===q.answer?1:0);save();renderSession();};$$('[data-score]').forEach(b=>b.onclick=()=>{commitRating(s,q,Number(b.dataset.score));save();renderSession();});if($('#continue'))$('#continue').onclick=advance;}
function ratings(){return '<div class="controls ratings"><button class="rate" data-score="0">Nicht gewusst</button><button class="rate" data-score="0.5">Teilweise</button><button class="rate" data-score="1">Gewusst</button></div>';}
function advance(){const s=data.session;s.revealed=false;if(s.pos<s.ids.length-1)s.pos++;else s.phase='result';save();goto(renderSession);}
function submitExam(){const s=data.session;const empty=s.ids.filter(id=>{const r=s.responses[id];return !r||!r.choice&&!r.text?.trim();}).length;if(!confirm(empty?`${empty} unbeantwortete Fragen werden mit 0 bewertet. Prüfung jetzt abgeben?`:'Prüfung abgeben und Lösungen anzeigen?'))return;
for(const id of s.ids){const q=byId.get(id),r=s.responses[id]||{};if(isChoice(q,s))commitRating(s,q,r.choice===q.answer?1:0);else if(!r.text?.trim())commitRating(s,q,0);}
s.phase=s.ids.some(id=>!s.responses[id]?.recorded)?'review':'result';save();goto(renderSession);}
function renderReview(){const s=data.session;const id=s.ids.find(id=>!s.responses[id]?.recorded);if(!id){s.phase='result';save();renderResult();return;}const q=byId.get(id),r=s.responses[id],remaining=s.ids.filter(id=>!s.responses[id]?.recorded).length;
$('#app').innerHTML=`<div class="question-shell"><div class="qtop"><button class="textbtn" id="pause">← Pause</button><span class="muted">${remaining} offene Antworten zu bewerten</span></div><section class="card qcard"><div class="eyebrow">Prüfung abgegeben · Selbstbewertung</div><h1>${esc(q.question)}</h1>${imageHTML(q)}<h3>Deine Antwort</h3><p style="white-space:pre-wrap">${esc(r.text)}</p>${answerHTML(q)}<p class="muted">Vergleiche die fachlichen Kernpunkte. Sinngemäß richtige Antworten zählen.</p>${ratings()}</section></div>`;$('#pause').onclick=()=>goto(home);$$('[data-score]').forEach(b=>b.onclick=()=>{commitRating(s,q,Number(b.dataset.score));save();goto(renderSession);});}
function renderResult(){const s=data.session;const total=s.ids.length,score=s.ids.reduce((n,id)=>n+(s.responses[id]?.score||0),0),pct=Math.round(100*score/total);if(!s.saved){data.history.push({at:Date.now(),mode:s.mode,total,score});data.history=data.history.slice(-50);s.saved=true;save();}const wrong=s.ids.filter(id=>(s.responses[id]?.score||0)<1),open=s.ids.filter(id=>!isChoice(byId.get(id),s)).length;
$('#app').innerHTML=`<div class="question-shell"><div class="eyebrow muted">${modes[s.mode]} abgeschlossen</div><h1>${pct>=85?'Guter Kurs. Weiter so.':pct>=60?'Schon viel an Bord.':'Die nächste Runde bringt dich weiter.'}</h1><section class="card space"><div class="score">${pct}<span style="font-size:1.8rem;letter-spacing:0"> %</span></div><p><strong>${score.toLocaleString('de-DE')} von ${total} Punkten</strong> · ${wrong.length} Fragen zum Festigen</p><p class="muted">${open?`${open} offene bzw. praktische Antworten wurden von dir selbst bewertet. `:''}Übungsergebnis, keine offizielle Bestehensentscheidung.</p><div class="controls space"><button class="primary" id="retry" ${wrong.length?'':'disabled'}>Unsichere wiederholen</button><button class="secondary" id="done">Zur Übersicht</button></div></section><div class="sectionhead"><h2>Deine Antworten</h2></div>${s.ids.map(id=>{const q=byId.get(id),r=s.responses[id]||{};return `<details><summary><span class="badgelabel">${r.score===1?'✓':r.score===.5?'◐':'↻'} ${r.score||0}/1</span>${esc(q.question)}</summary>${imageHTML(q)}${r.choice||r.text?`<p><strong>Deine Antwort:</strong> ${esc(r.choice||r.text)}</p>`:'<p class="muted">Mündlich beantwortet oder übersprungen.</p>'}${answerHTML(q)}</details>`}).join('')}</div>`;$('#done').onclick=()=>{data.session=null;save();goto(home);};$('#retry').onclick=()=>{data.session=null;start('learn',null,wrong.length,wrong.map(id=>byId.get(id)));};}
function catalog(){view='catalog';$('#app').innerHTML=`<div class="info"><button class="textbtn" id="back">← Zur Übersicht</button><h1>Dein Fragenkatalog</h1><p class="muted">${Q.length} Fragen mit Musterlösungen und Seitenverweisen.</p><div class="filterline"><div><label for="search">Fragen durchsuchen</label><input type="search" id="search" placeholder="z. B. Bora, Kompass, Funk …" value="${esc(catalogText)}"></div><div><label for="topicFilter">Thema</label><select id="topicFilter"><option value="">Alle Themen</option>${topics.map(t=>`<option ${t===catalogTopic?'selected':''}>${esc(t)}</option>`).join('')}</select></div></div><div id="catalogResults"></div></div>`;$('#back').onclick=()=>goto(home);$('#search').oninput=e=>{catalogText=e.target.value;catalogResults();};$('#topicFilter').onchange=e=>{catalogTopic=e.target.value;catalogResults();};catalogResults();}
function catalogResults(){const text=catalogText.trim().toLocaleLowerCase('de');const qs=Q.filter(q=>(!catalogTopic||q.topic===catalogTopic)&&(!text||`${q.question} ${q.answer} ${q.topic}`.toLocaleLowerCase('de').includes(text)));$('#catalogResults').innerHTML=`<p class="muted">${qs.length} Treffer</p>${qs.length?qs.map(q=>`<details class="catalogitem"><summary><span class="muted" style="font-size:.8rem">${esc(q.topic)} · S. ${q.page}</span><br>${esc(q.question)}</summary>${imageHTML(q)}${answerHTML(q)}</details>`).join(''):'<p class="empty">Keine passenden Fragen. Versuche einen anderen Suchbegriff.</p>'}`;}
function download(name,obj){const url=URL.createObjectURL(new Blob([JSON.stringify(obj,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1500);}
function info(){view='info';$('#app').innerHTML=`<div class="info"><button class="textbtn" id="back">← Zur Übersicht</button><h1>Alles für eure Lernreise.</h1><section class="card space"><h2>Auf dem Handy</h2><p><strong>iPhone:</strong> Den Link in Safari öffnen, das Teilen-Menü wählen und „Zum Home-Bildschirm“ antippen.</p><p><strong>Android:</strong> In Chrome öffnen und im Menü „Zum Startbildschirm hinzufügen“ bzw. „App installieren“ wählen.</p><p id="offlineInfo" class="muted">Offline-Status wird geprüft …</p><p>Für einen Offline-Test die App zuerst vollständig online laden, dann Flugmodus einschalten und erneut öffnen. Die externen Quellenlinks brauchen Internet. Der Zugriff auf die veröffentlichte Website kann eine Anmeldung verlangen.</p><h2>Gemeinsam lernen</h2><p>Ihr verwendet denselben Katalog, aber jeder lernt auf seinem Gerät. Ein Link allein hebt die Zugriffsfreigabe der Website nicht auf: Paola muss bei privater Veröffentlichung zusätzlich Zugriff erhalten.</p><button class="secondary" id="share">App-Link teilen</button><p class="muted">Partnerprüfung: Der Lernstand wird dem gerade verwendeten Gerät zugerechnet.</p></section><section class="card space"><h2>Fortschritt sichern</h2><p>Antworten und Lernstand bleiben lokal. Beim Löschen der Browserdaten können sie verloren gehen. Safari und die installierte App können getrennte Speicher verwenden; bei Bedarf die Sicherung übertragen.</p><div class="tools"><button class="primary" id="export">Fortschritt exportieren</button><button class="secondary" id="importBtn">Sicherung importieren</button></div><input class="sr-only" type="file" accept="application/json,.json" id="import"><p class="muted">Der Import ersetzt deinen aktuellen Lernstand nach Rückfrage. Die laufende Runde wird dabei beendet.</p><a href="./fragenkatalog.json" download="adria-fragenkatalog.json">Gesamten Fragenkatalog herunterladen</a></section><section class="card space"><h2>Wie die Bewertung funktioniert</h2><p>Auswahlfragen haben genau eine richtige Antwort. Offene und praktische Fragen bewertest du anhand der Musterlösung: nicht gewusst = 0, teilweise = ½, gewusst = 1 Punkt.</p><p>In der Testprüfung bleiben Lösungen bis zur Abgabe verborgen. Danach folgt die Selbstbewertung offener Antworten. Die zufällige Auswahl verteilt sich möglichst gleichmäßig über die Themen; das ist keine amtliche Prüfungsverteilung.</p><p>Als „sicher“ zählt eine Frage nach zwei richtigen Bewertungen in Folge. Richtige Fragen werden in wachsenden Abständen fällig; Fehler kommen früher wieder.</p><h2>Grundlage & fachliche Hinweise</h2><p>Eigenständig formulierter Lernkatalog auf Grundlage des verlinkten AC-Nautik-Skripts. Abgedeckt sind die Lernkapitel S. 5–59, vertieft durch den Fragenblock S. 60–64. Werbung, Preise und Anfahrtsinformationen sind kein Prüfungsstoff. Abkürzungen und Fachbegriffe wurden sinngemäß aufbereitet.</p><p>Erkannte Fehler bei Lichterführung, Schallsignalen, Vorrang und Funkbegriffen wurden präzisiert. Kroatische Abstandsregeln wurden gegen NN 52/2025 und die Änderung NN 40/2026 geprüft. Entsprechende Antworten tragen Hinweise. Stand: 11.09.2026.</p><p>Die historische Ausrüstungsliste, sämtliche Einreiseformalitäten und lokalen Funkkanäle wurden nicht als vollständige aktuelle Rechtsauskunft übernommen. Klärt abweichende Lehrmeinungen mit eurer Kursleitung. Knoten und Kartenarbeit auch praktisch üben.</p><p><strong>Lerntrainer, kein offizieller Prüfungskatalog und kein Hilfsmittel zur Navigation in Echtzeit.</strong></p>${Object.values(B.sources).map(s=>`<p><a href="${s.url}" target="_blank" rel="noopener">${esc(s.title)} ↗</a></p>`).join('')}</section>${data.history.length?`<section class="card space"><h2>Letzte Lernrunden</h2>${data.history.slice(-10).reverse().map(h=>`<p class="row"><span>${new Date(h.at).toLocaleDateString('de-DE')} · ${modes[h.mode]||'Lernrunde'}</span><strong>${h.score}/${h.total}</strong></p>`).join('')}</section>`:''}</div>`;
$('#back').onclick=()=>goto(home);$('#share').onclick=async()=>{const url=location.origin+location.pathname;try{if(navigator.share)await navigator.share({title:'Adria · Küstenpatent Trainer',url});else{await navigator.clipboard.writeText(url);toast('Link kopiert. Zugriffsfreigabe für Paola beachten.');}}catch(e){if(e.name!=='AbortError')toast('Bitte kopiere den Link aus der Adresszeile.');}};$('#export').onclick=()=>download('adria-fortschritt-'+new Date().toISOString().slice(0,10)+'.json',{version:1,cards:data.cards,history:data.history});$('#importBtn').onclick=()=>$('#import').click();$('#import').onchange=async e=>{const f=e.target.files[0];if(!f)return;try{if(f.size>3000000)throw Error('Datei zu groß');const parsed=JSON.parse(await f.text());if(parsed.version!==1)throw Error('Unbekanntes Format');const cards=validCards(parsed.cards);if(!Object.keys(cards).length)throw Error('Keine bekannten Lernstände');if(!confirm(`Aktuellen Lernstand durch ${Object.keys(cards).length} Einträge aus der Sicherung ersetzen?`))return;data={version:1,cards,history:Array.isArray(parsed.history)?parsed.history.filter(h=>h&&Number.isFinite(h.at)&&Number.isFinite(h.total)&&h.total>0&&Number.isFinite(h.score)&&h.score>=0&&h.score<=h.total&&modes[h.mode]).slice(-50):[],session:null};save();toast('Lernstand importiert.');goto(home);}catch(e){toast('Import fehlgeschlagen: '+e.message);}};updateOffline();}
let offlineReady=false;function updateOffline(){const online=navigator.onLine!==false;$('#connection').textContent=!online?'Offline':offlineReady?'Offline bereit':'Online';if($('#offlineInfo'))$('#offlineInfo').textContent=offlineReady?'Die Lerninhalte sind auf diesem Gerät für Offline-Nutzung gespeichert.':'Offline-Inhalte sind noch nicht bestätigt. Bitte online bleiben, bis oben „Offline bereit“ erscheint.';}
window.addEventListener('online',updateOffline);window.addEventListener('offline',updateOffline);$('#brand').onclick=e=>{e.preventDefault();save();goto(home);};$('#infoBtn').onclick=()=>goto(info);home();updateOffline();
if('serviceWorker'in navigator){navigator.serviceWorker.register('./sw.js',{scope:'./'}).then(()=>navigator.serviceWorker.ready).then(reg=>{const ch=new MessageChannel();ch.port1.onmessage=e=>{offlineReady=e.data?.ready===true;updateOffline();};reg.active?.postMessage({type:'CHECK_OFFLINE'},[ch.port2]);}).catch(()=>{offlineReady=false;updateOffline();});}
// Optional browser agent interface; learning is driven by the same visible actions.
const ctx=document.modelContext;if(ctx?.registerTool){try{Promise.resolve(ctx.registerTool({name:'start_practice_round',title:'Lernrunde starten',description:'Startet eine sichtbare Lernrunde. Ersetzt keine laufende Runde.',inputSchema:{type:'object',properties:{topic:{type:'string',enum:topics},count:{type:'integer',minimum:1,maximum:30}},additionalProperties:false},annotations:{readOnlyHint:false},execute(input){if(!input||typeof input!=='object'||Object.keys(input).some(k=>!['topic','count'].includes(k))||input.topic!==undefined&&!topics.includes(input.topic)||input.count!==undefined&&(!Number.isInteger(input.count)||input.count<1||input.count>30))throw Error('Ungültige Lernrunde');if(data.session&&data.session.phase!=='result')throw Error('Es läuft bereits eine Runde.');start('learn',input.topic||null,input.count||10);return {started:true,questions:data.session.ids.length,mode:'learn'};}})).catch(()=>{});}catch{}}
// Pure/state helpers exposed to the offline validation harness.
window.AdriaCore={choose,makeSession,validCards,sessionValid,progress,record,commitRating,getData:()=>data,start,home};
})();
